    addJumpRel8(opcode, labelName) {
        this.buffer.push(opcode);
        this.labelPatches.push({ 
            offset: this.buffer.length, 
            type: 'rel8', 
            target: labelName, 
            instSize: 1 
        });
        this.buffer.push(0x00); // Placeholder
    }

    // Jump to a label (Long jump 32-bit)
